from pathlib import Path
import subprocess,json,shlex,time,selectors,hashlib
w=Path(__file__).parent;lab=w.parent.parent;manifest=json.loads((w/'probe-source-hashes.json').read_text());remote=manifest['remote_directory'];boot=json.loads((w/'boot.json').read_text());peers=[x['address'] for x in boot]
label='pf28-close-remote-a';prefix=lab/'evidence'/label;assert not list(prefix.parent.glob(label+'-*'))
sshs=[['ssh','-F',str(w/'ssh_config'),f'ssi-lab-{n+1}'] for n in range(2)]
processes=[];errors=[];before=[];cursors=[];actions=[];outputs=[[],[]];comment='sshpool-pf28-close-remote';chain='sudo nft -j -a list chain inet sshpool_ssi_lab input'
def line(n,timeout=15):
 sel=selectors.DefaultSelector();sel.register(processes[n].stdout,selectors.EVENT_READ)
 ready=sel.select(timeout);sel.close()
 if not ready:raise RuntimeError('worker response timeout '+str(n))
 value=processes[n].stdout.readline();outputs[n].append(value)
 if not value:raise RuntimeError('worker EOF '+str(n))
 return json.loads(value)
def command(n,payload):
 processes[n].stdin.write(json.dumps(payload)+'\n');processes[n].stdin.flush();row=line(n);actions.append({'node':n,'command':payload,'response':row});return row
try:
 for n,ssh in enumerate(sshs):
  assert subprocess.check_output(ssh+['uname -r'],text=True).strip()=='7.1.0-rc3-sshpool-gvm-pf28'
  observed=subprocess.check_output(ssh+['sha256sum '+shlex.join(remote+'/'+x for x in manifest['hashes'])],text=True)
  assert [x.split()[0] for x in observed.splitlines()]==list(manifest['hashes'].values())
  kernel_hash=subprocess.check_output(ssh+['sha256sum /var/lib/sshpool/boot-pf28/vmlinuz-7.1.0-rc3-sshpool-gvm-pf28'],text=True)
  assert kernel_hash.split()[0]==json.loads((w/'pf28-build-hashes.json').read_text())['kernel']
  Path(str(prefix)+f'-node{n}-hashes.txt').write_text(kernel_hash+observed)
  before.append(json.loads(subprocess.check_output(ssh+[chain])))
  cursors.append(subprocess.check_output(ssh+['sudo journalctl -k -b -n 0 --show-cursor --no-pager'],text=True).split('-- cursor: ')[1].strip())
  rule=''.join(f'insert rule inet sshpool_ssi_lab input ip saddr {peers[1-n]} tcp {side} {{ 37710, 37711 }} accept comment "{comment}"\n' for side in ('dport','sport'))
  subprocess.run(ssh+['sudo nft -f -'],input=rule.encode(),check=True)
 for n,ssh in enumerate(sshs):
  cmd=['sudo','python3',remote+'/probe-kernel-close.py','--require-kernel','7.1.0-rc3-sshpool-gvm-pf28','--mode','remote','--node',str(n),'--peers',*peers,'--output',remote+'/'+label+f'-node{n}.json']
  err=Path(str(prefix)+f'-node{n}-stderr.log').open('x');errors.append(err)
  processes.append(subprocess.Popen(ssh+[shlex.join(cmd)],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=err,text=True,bufsize=1))
 for n in range(2):assert line(n)['ready']
 for n,op,reverse in ((0,'write',False),(1,'read',False),(1,'write',True),(0,'read',True)):
  reply=command(n,{'op':op,'reverse':reverse});assert reply['op']==op
 for n in range(2):processes[n].stdin.write('{"op":"close"}\n');processes[n].stdin.flush()
 for n in range(2):
  result=line(n,10);assert not result['errors'],result
  processes[n].stdin.close();processes[n].wait(10);assert processes[n].returncode==0
finally:
 for p in processes:
  if p.poll() is None:
   try:p.stdin.write('{"op":"close"}\n');p.stdin.flush();p.wait(10)
   except (BrokenPipeError,ValueError,subprocess.TimeoutExpired):pass
 for err in errors:err.close()
 for n,ssh in enumerate(sshs[:len(before)]):
  active=json.loads(subprocess.check_output(ssh+[chain]));handles=[x['rule']['handle'] for x in active['nftables'] if x.get('rule',{}).get('comment')==comment]
  for h in handles:subprocess.run(ssh+[f'sudo nft delete rule inet sshpool_ssi_lab input handle {h}'],check=True)
  after=json.loads(subprocess.check_output(ssh+[chain]));assert before[n]==after
  Path(str(prefix)+f'-node{n}-firewall.json').write_text(json.dumps({'before':before[n],'after':after,'active':active},indent=2)+'\n')
  raw=subprocess.run(ssh+['sudo cat '+remote+'/'+label+f'-node{n}.json'],capture_output=True)
  if raw.returncode==0:Path(str(prefix)+f'-node{n}-probe.json').write_bytes(raw.stdout)
  host=subprocess.check_output(ssh+['sudo journalctl -k -b --no-pager --after-cursor='+shlex.quote(cursors[n])]);Path(str(prefix)+f'-node{n}-host.log').write_bytes(host)
  Path(str(prefix)+f'-node{n}-stdout.log').write_text(''.join(outputs[n]))
 Path(str(prefix)+'-actions.json').write_text(json.dumps(actions,indent=2)+'\n')
print(json.dumps({'label':label,'exit':[p.returncode for p in processes],'actions':actions}),flush=True)

from pathlib import Path
import json,hashlib,importlib.util
w=Path(__file__).parent;work=w.parent;lab=work.parent;repo=Path('/Users/zjarlin/projects/sshpool')
spec=importlib.util.spec_from_file_location('close',repo/'scripts/ssi-lab/check-kernel-close.py');checker=importlib.util.module_from_spec(spec);spec.loader.exec_module(checker)
def js(p):return json.loads(p.read_text())
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def capture(label,analyse=True):
 p=lab/'evidence'/label;record=Path(str(p)+'-probe.json');hashes=Path(str(p)+'-hashes.txt')
 row={'label':label,'record':js(record),'record_sha256':digest(record),'host_log':Path(str(p)+'-host.log').read_text(),'firewall':js(Path(str(p)+'-firewall.json')),'runtime_hashes':{Path(line.split()[1]).name:line.split()[0] for line in hashes.read_text().splitlines()}}
 result=Path(str(p)+'-result.json')
 if result.exists():row['run']=js(result)
 if analyse:row['analysis']=checker.inspect(row['record'])
 return row
manifests=[js(w/name) for name in ('probe-source-hashes.json','probe-source-hashes-v7.json')]
versions={m['hashes']['probe-kernel-close.py']:m['hashes'] for m in manifests}
evidence={'scope':'Two dedicated x86 VMs on one physical ESXi host; real KVM with no vCPU or disk. Native close does not certify QEMU device shutdown.','whole_vm_shutdown_verified':False,'build':js(w/'pf28-build-hashes.json'),'original_source_sha256':js(work/'original-hashes.json'),'probe_source_versions':versions,'source_sha256':{},'probes':[],'remote_probes':[],'prior_observations':[],'capture_sources':[]}
for name in ['scripts/ssi-lab/check-kernel-close.py','scripts/ssi-lab/probe-kernel-close.py','scripts/ssi-lab/experiments/kernel-dsm-close.patch']:
 evidence['source_sha256'][name]=digest(repo/name)
for p in sorted((lab/'evidence').glob('pf28-close-*-result.json')):
 label=p.name.removesuffix('-result.json')
 result=js(p)
 if result['exit'] or result['capture_exit']:
  row=capture(label,False);row['interpretation']='The send-pressure setup did not reach socket send blocking. Repeated requests transferred page ownership and then waited for a reverse fetch. These failed preparations are retained and do not certify shutdown.';evidence['prior_observations'].append(row);continue
 row=capture(label);evidence['probes'].append(row)
assert len(evidence['probes'])==40
for n in range(2):evidence['remote_probes'].append(capture(f'pf28-close-remote-a-node{n}'))
evidence['remote_actions']=js(lab/'evidence/pf28-close-remote-a-actions.json')
for label,note in [('pf27-close-pair-node1-b','Both close ioctls returned zero but one root thread remained frozen. PF28 wakes each transition and waits for root_done.'),('pf27-close-root-signal-node0-a','The probe used a process-directed signal rather than tgkill. This is not evidence about the in-kernel directed cancellation path.'),('pf26-close-remote-a-node0','PF26 already transferred actual page bytes between the two hosts, but listener freezing and root completion were strengthened in PF27/PF28.'),('pf26-close-remote-a-node1','Companion host capture for the preserved PF26 cross-host run.')]:
 row=capture(label,False);row['interpretation']=note;evidence['prior_observations'].append(row)
for root in (work/'first-build',work/'second-build'):
 evidence.setdefault('prior_builds',[]).append({p.name:js(p) for p in root.glob('*hashes.json')})
for name in ['run_probe.py','run_probe_v6.py','run_probe_v7.py','run_matrix.py','run_remote.py','build_native_evidence.py','probe-kernel-close.py','probe-kernel-close-v6.py','probe-kernel-close-v7.py']:
 p=w/name;evidence['capture_sources'].append({'name':name,'sha256':digest(p),'text':p.read_text()})
restoration=w/'restoration.json'
if restoration.exists():evidence['restoration']=js(restoration)
for path in (work/'build-pf28.log',work/'package-pf28.log'):
 if path.exists():evidence[path.stem.replace('-','_')]=path.read_text()
out=repo/'docs/evidence/ssi-kernel-close-20261108.json';out.write_text(json.dumps(evidence,indent=2)+'\n');print(out, out.stat().st_size)
